export async function createScene(engine, canvas, BABYLON) {
  var scene = new BABYLON.Scene(engine);
  scene.useRightHandedSystem = true;

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.alpha = Math.PI / 2;
  camera.beta = Math.PI / 2;
  camera.radius = 10;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.zoomToMouseLocation = true;

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.7;

  let plane = BABYLON.MeshBuilder.CreatePlane(
    "plane",
    { width: canvas.getBoundingClientRect().width / 100, height: canvas.getBoundingClientRect().height / 100 },
    scene
  );

  let materialRef;
  const mousePos = { x: 0, y: 0 };

  // Vertex shader
  const vertexShader = `
      precision highp float;
      
      attribute vec3 position;
      attribute vec2 uv;
      
      uniform mat4 worldViewProjection;
      
      varying vec2 vUV;
      
      void main() {
        vUV = uv;
        gl_Position = worldViewProjection * vec4(position, 1.0);
      }
    `;

  // Fragment shader with ray marching metaballs
  const fragmentShader = `
      precision highp float;
      
      varying vec2 vUV;
      
      uniform float time;
      uniform vec2 resolution;
      uniform vec2 mouse;
      
      // SDF for sphere
      float sdSphere(vec3 p, float r) {
        return length(p) - r;
      }
      
      // Smooth minimum function for metaball effect
      float smin(float a, float b, float k) {
        float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
        return mix(b, a, h) - k * h * (1.0 - h);
      }
      
      // Scene SDF with multiple metaballs
      float map(vec3 p) {
        // Main metaball following mouse - 직접 마우스 좌표 사용
        vec3 mousePos3D = vec3(mouse.x, mouse.y, 0.0);
        float d1 = sdSphere(p - mousePos3D, 0.3);
        
        // Animated metaballs
        vec3 pos2 = vec3(sin(time * 1.2) * 0.8, cos(time * 0.8) * 0.6, sin(time * 0.5) * 0.3);
        float d2 = sdSphere(p - pos2, 0.25);
        
        vec3 pos3 = vec3(cos(time * 1.5) * 0.6, sin(time * 1.8) * 0.8, cos(time * 0.7) * 0.4);
        float d3 = sdSphere(p - pos3, 0.2);
        
        vec3 pos4 = vec3(sin(time * 0.9) * 0.9, cos(time * 1.3) * 0.5, sin(time * 1.1) * 0.2);
        float d4 = sdSphere(p - pos4, 0.18);
        
        // Combine with smooth minimum for metaball effect
        float result = smin(d1, d2, 0.3);
        result = smin(result, d3, 0.3);
        result = smin(result, d4, 0.3);
        
        return result;
      }
      
      // Calculate normal using gradient
      vec3 calcNormal(vec3 p) {
        const float eps = 0.001;
        vec2 h = vec2(eps, 0.0);
        return normalize(vec3(
          map(p + h.xyy) - map(p - h.xyy),
          map(p + h.yxy) - map(p - h.yxy),
          map(p + h.yyx) - map(p - h.yyx)
        ));
      }
      
      // Ray marching
      float rayMarch(vec3 ro, vec3 rd) {
        float t = 0.0;
        for (int i = 0; i < 80; i++) {
          vec3 p = ro + t * rd;
          float d = map(p);
          if (d < 0.001 || t > 10.0) break;
          t += d;
        }
        return t;
      }
      
      void main() {
        vec2 uv = (vUV - 0.5) * 2.0;
        uv.x *= resolution.x / resolution.y;
        
        // Ray setup
        vec3 ro = vec3(0.0, 0.0, -2.0); // Ray origin
        vec3 rd = normalize(vec3(uv, 1.0)); // Ray direction
        
        // Ray march
        float t = rayMarch(ro, rd);
        
        vec3 color = vec3(0.0);
        
        if (t < 10.0) {
          vec3 p = ro + t * rd;
          vec3 normal = calcNormal(p);
          
          // Lighting
          vec3 lightPos = vec3(2.0, 2.0, -1.0);
          vec3 lightDir = normalize(lightPos - p);
          float diff = max(dot(normal, lightDir), 0.0);
          
          // Specular
          vec3 viewDir = normalize(-rd);
          vec3 reflectDir = reflect(-lightDir, normal);
          float spec = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);
          
          // Color based on position and time
          vec3 baseColor = vec3(0.2, 0.6, 1.0);
          baseColor += vec3(sin(p.x * 3.0 + time), sin(p.y * 3.0 + time * 1.2), sin(p.z * 3.0 + time * 0.8)) * 0.3;
          
          color = baseColor * (0.3 + diff * 0.7) + vec3(1.0) * spec * 0.5;
          
          // Add some glow effect
          float glow = 1.0 - smoothstep(0.0, 1.0, t / 3.0);
          color += vec3(0.1, 0.3, 0.8) * glow * 0.3;
        } else {
          // Background gradient
          color = mix(vec3(0.05, 0.05, 0.1), vec3(0.0, 0.0, 0.0), length(uv) * 0.5);
        }
        
        gl_FragColor = vec4(color, 1.0);
      }
    `;

  // Create shader material
  const material = new BABYLON.ShaderMaterial(
    "metaball",
    scene,
    {
      vertex: "custom",
      fragment: "custom",
    },
    {
      attributes: ["position", "uv"],
      uniforms: ["worldViewProjection", "time", "resolution", "mouse"],
    }
  );

  // Set shader source
  BABYLON.Effect.ShadersStore["customVertexShader"] = vertexShader;
  BABYLON.Effect.ShadersStore["customFragmentShader"] = fragmentShader;

  materialRef = material;
  materialRef.backFaceCulling = false;
  plane.material = material;

  // Set initial uniforms
  material.setVector2("resolution", new BABYLON.Vector2(canvas.width, canvas.height));
  material.setVector2("mouse", new BABYLON.Vector2(0.0, 0.0));

  scene.onPointerObservable.add((pointerInfo) => {
    if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERMOVE) {
      const event = pointerInfo.event;
      const rect = canvas.getBoundingClientRect();

      // UV 기준: (0,0) ~ (1,1)
      let uvX = (event.clientX - rect.left) / rect.width;
      let uvY = (event.clientY - rect.top) / rect.height;

      // 셰이더의 vUV → NDC 변환과 동일하게 처리
      let x = (uvX - 0.5) * 3.0;
      let y = (uvY - 0.5) * 3.0; // 위가 +Y이므로 반전 안 함

      // 셰이더에서 x *= resolution.x / resolution.y 되어 있음
      const aspect = rect.width / rect.height;
      x *= aspect;

      mousePos.x = x;
      mousePos.y = -y;
    }
  }, BABYLON.PointerEventTypes.POINTERMOVE);

  const handleResize = () => {
    engine.resize();
    if (plane) {
      plane.dispose();
    }

    // 새 평면 크기에 맞게 재생성 (선택 사항)
    const rect = canvas.getBoundingClientRect();
    const newPlane = BABYLON.MeshBuilder.CreatePlane(
      "plane",
      { width: canvas.getBoundingClientRect().width / 100, height: canvas.getBoundingClientRect().height / 100 },
      scene
    );
    newPlane.material = materialRef;
    plane = newPlane;

    if (materialRef) {
      materialRef.setVector2("resolution", new BABYLON.Vector2(rect.width, rect.height));
    }
  };

  window.addEventListener("resize", handleResize);

  // Render loop
  const startTime = Date.now();
  scene.registerBeforeRender(() => {
    const currentTime = (Date.now() - startTime) / 1000;

    if (materialRef) {
      materialRef.setFloat("time", currentTime);
      materialRef.setVector2("mouse", new BABYLON.Vector2(mousePos.x, mousePos.y));

      console.log(currentTime, mousePos.x, mousePos.y);
    }
  });

  return scene;
}
